"""docich#4668: an unread max HP must not let near-dead generals attack.

ch1 run 2026-11-19 3-11: クランベリー (HP 7 vs 37), コリアンダー (0 vs 24) and
リーキ (0 vs 8) were sent at castles and died on arrival. The gate only blocked
hp <= 1 when the maximum was unread, so every 2..19 HP general passed.
"""
from docich.hanjuku_speedrun.hanjuku.strategy import replan


def memory(hp, max_hp=None):
    row = {'hp': hp}
    if max_hp is not None:
        row['max_hp'] = max_hp
    return {'general_statuses': {'statuses': {'リーキ': row}}}


def test_an_unread_maximum_uses_the_absolute_floor():
    assert replan._too_hurt_to_attack(memory(7), 'リーキ')
    assert replan._too_hurt_to_attack(memory(19), 'リーキ')
    assert not replan._too_hurt_to_attack(memory(20), 'リーキ')
    assert not replan._too_hurt_to_attack(memory(45), 'リーキ')


def test_a_measured_maximum_keeps_the_ratio():
    assert replan._too_hurt_to_attack(memory(10, 60), 'リーキ')
    assert not replan._too_hurt_to_attack(memory(15, 60), 'リーキ')


def test_unread_hp_is_not_evidence():
    assert not replan._too_hurt_to_attack({}, 'リーキ')
    assert not replan._too_hurt_to_attack({'general_statuses': {'statuses': {}}}, 'リーキ')
